DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0410000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 41, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "41", "printedPageNumber": 41, "pdfPageNumber": 424, "sequenceIndex": 31, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0410000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "for neglecting Maghrib and till dawn for neglecting Ishaa. The serpent will keep on thrashing him thus till the Last Day. Each blow pushes him to a depth of seventy arm''s length. The punishments will last till the Day of Judgement.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Those after resurrection are: His reckoning will be a hard one; Allah will be angry with him; and he will be thrown into the Fire. According to one report, he will have following three lines inscribed on his forehead:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "''O you who neglected Allah''s duty''\n''O you who has deserved Allah''s wrath.''\n''Now despair of Allah''s mercy, as you neglected your duty to Allah.''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Eminent theologians like Ibn Hajr, Abu Laith Samarqandi (Rahmatullah alaihim), and others, have mentioned this hadith in their books. Although I have not been able to trace the text in original books on hadith, yet other hadiths, some of which have already been mentioned and some are to follow, corroborate its meaning. Neglect of salaat, as has been stated above, leads one to kufr; hence no punishment is too severe for this offence. But it should be borne in mind that even after the declaration of a person as being guilty, Allah is free to pardon him as and when He pleases. He says in His Holy Book:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَنْ يَشَاءُ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! Allah pardoneth not that partners should be ascribed unto Him. Allah pardoneth all (save that) whom He will. (IV: 116)\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "If then it pleases Allah to pardon anybody neglecting salaat, it will be most fortunate; but who can be sure of this fortune?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is also stated in hadith that there will be three courts to be held by Allah on the Day of Judgement. The first will judge between kufr and islaam and there will be no pardon. The second will be to judge the duties and conduct of one towards another. All aggrieved shall be compensated there; compensation will either be realised from the aggressor or paid by Allah Himself, if He pleases to pardon anybody. The third will deal with duties towards Allah. Here the doors of Allah''s mercy will be thrown wide-open and He shall pardon anybody He wills. In the light of all that has", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0420000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 42, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "42", "printedPageNumber": 42, "pdfPageNumber": 425, "sequenceIndex": 32, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0420000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "been said above, it must be clearly understood that we deserve the punishments that have been laid down for our commission of sins, but the All-embracing mercy of Allah overrides everything and knows no bounds.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It was a habit with the Prophet (Sallallaho alaihe wasallam) to enquire from the companions, just after Fajr, if anybody had seen any dream. He would then interpret the dream as related to him. One day, after enquiring from others as usual, the Prophet (Sallallaho alaihe wasallam) himself narrated a long dream in which two men came and took him with them. Besides others he reported certain events which he happened to see in his dream. He said: \"I noticed the head of a person being crushed with a heavy stone. It was struck with such force that, after crushing the head, the stone rolled down over a long distance. The head would assume its normal shape by the time the stone was brought back for repeating the process. This continued incessantly. On inquiring from one of my companions, I was told that the person first learnt the Qur''an, but failed to practise upon it and also used to go to sleep without offering the fardh salaat.\" There is another similar narration, in which the Prophet (Sallallaho alaihe wasallam) is reported to have seen (in his dream) a group of people being treated likewise. Jibra-eel (Alayhis salaam) informed him on his query that those were the persons who used to neglect their salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Mujahid (Rahmatullah alaih) says, \"Allah blesses the people who guard their salaat, just as He blessed Hadhrat Ibrahim (Alayhis salaam) and his descendants.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"If a person dies with sincere Imaan, observing the commandments of Allah, performing salaat, and paying Zakaat, when he dies Allah is pleased with him.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) also narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Allah says, ''I hold back retribution, deserved by a locality, when I see therein some people who frequently visit the musjid, love one another for My sake, and pray for forgiveness in the hours of darkness.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Darda (Radhiyallaho anho) wrote to Hadhrat Salmaan: \"Spend most of your time in the musjid. I have heard the Prophet (Sallallaho alaihe wasallam) saying, ''The musjid is the abode of the pious. Allah has taken upon Himself to bless the person who spends most of", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0430000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 43, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "43", "printedPageNumber": 43, "pdfPageNumber": 426, "sequenceIndex": 33, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0430000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "his time in the mosque. Allah shall keep him in comfort and shall make him cross the Siraat with great ease. Surely Allah is pleased with such a person.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Mas''ood (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"The masaajid are the Houses of Allah, and people coming therein are His visitors. When everybody treats his visitors kindly, why should Allah not be kind to His guests?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"Allah loves the person who is attached to the musjid.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"When a dead person is laid in the grave, even before the people present at his burial clear off, Munkar and Nakeer visit him. Then, if the person is a Mo''min, his good practices encircle him; salaat comes close to his head, Zakaat to his right, Fast to his left, and the remaining good deeds towards his feet, so that none can approach him. Even the angels do the necessary questioning while standing at a distance.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "One of the companions reports that, when the inmates of the Prophet''s house were hard-pressed in any way, he would enjoin salaat on them and recite the following verse:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَى", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon thy people and be constant therein. We ask not of thee a provision, We provide for thee. And the Hereafter is for the righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Asma (Radhiyallaho anha) narrates that she heard the Prophet (Sallallaho alaihe wasallam) saying, \"All the people will be gathered together on the Day of Judgement and they will all hear the voice of the announcing angel. He will say, ''where are those who glorified Allah in ease and adversity?'' A group will rise up and enter Paradise without reckoning. It will then be announced, ''where are those who forsook their beds and spent their nights in worship?'' Another group will rise up and enter Paradise without reckoning. The angel will again announce, ''where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;